from pathlib import Path
import base64, gzip, hashlib, json
data = gzip.decompress(base64.b64decode(''))
p = Path('/marimo/domains/menu_planning/scripts/minimal_pairs/prepare_assets_v2.py')
assert hashlib.sha256(data).hexdigest() == '19236732753035d6f792e0a72c6e25fc47af3fcadcb2f161c1437bbc5938d90e'
if p.exists():
    assert p.read_bytes() == data
else:
    with p.open('xb') as f: f.write(data)
print(json.dumps({'path': str(p), 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()}))
